/**
 * 假的 `@deepseek-ai/schemastery`，只用于离线端到端测试。
 *
 * 真实实现会做严格校验并把默认值补全。测试里只需要"默认值真的被填上"，
 * 这样 `createTool` 拿到的 config 才与 DSH 运行时一致。
 */
function makeNode(meta = {}) {
  const node = {
    meta,
    default(value) {
      return makeNode({ ...meta, defaultValue: value })
    },
    optional() {
      return makeNode({ ...meta, optional: true })
    },
    description(text) {
      return makeNode({ ...meta, description: text })
    },
  }
  return node
}

function object(shape = {}) {
  return {
    __shape: shape,
    meta: { type: 'object' },
    default(value) {
      return { __shape: shape, meta: { type: 'object', defaultValue: value } }
    },
    description(text) {
      return { __shape: shape, meta: { type: 'object', description: text } }
    },
  }
}

const z = {
  object,
  string: () => makeNode({ type: 'string' }),
  number: () => makeNode({ type: 'number' }),
  boolean: () => makeNode({ type: 'boolean' }),
  array: () => makeNode({ type: 'array' }),
  any: () => makeNode({ type: 'any' }),
  /** 与真实实现同签名：返回 `[resolvedConfig, ...]`。 */
  resolve(raw, schema) {
    const shape = schema?.__shape ?? {}
    const out = {}
    for (const [key, node] of Object.entries(shape)) {
      const value = raw?.[key]
      if (value !== undefined) {
        out[key] = value
        continue
      }
      if (node?.meta?.defaultValue !== undefined) out[key] = node.meta.defaultValue
    }
    for (const [key, value] of Object.entries(raw ?? {})) if (!(key in out)) out[key] = value
    return [out]
  },
}

export { z }
export default z
